import{_ as t,o as p,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"CDS Squid: Cephadm","description":"","frontmatter":{"title":"CDS Squid: Cephadm","date":"2023-07-25T00:00:00.000Z","updated":"2023-07-26T00:00:00.000Z","tags":["Ceph","Cephadm","分布式存储","Orchestration","Kubernetes"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/CDS_Squid_-_Cephadm.md","filePath":"posts/2023/CDS_Squid_-_Cephadm.md","lastUpdated":1780459816000}'),s={name:"posts/2023/CDS_Squid_-_Cephadm.md"};function l(o,e,r,d,_,n){return p(),i("div",null,[...e[0]||(e[0]=[a("<p>本次会议主要围绕Cephadm的编排（Orchestration）与鱿鱼（Squid）发布计划展开。会议讨论了以下关键议题：</p><ol><li><p><strong>SMB支持</strong>： 讨论了在Ceph中添加SMB支持的计划，包括使用Samba和Samba共享代替NFS，并计划在Ceph AEM中重用相关工作。</p></li><li><p><strong>FBM二进制重构</strong>： 讨论了FBM二进制文件的重构计划，包括将其分解为更易管理的模块，并引入依赖项。</p></li><li><p><strong>NVMF支持</strong>： 讨论了在Ceph中添加NVMF支持的计划，计划在Squid发布周期中完成开发并测试。</p></li><li><p><strong>升级历史记录</strong>： 讨论了添加升级历史记录功能的需求，以便跟踪集群的升级路径和失败记录。</p></li><li><p><strong>改进测试覆盖率</strong>： 讨论了提高测试覆盖率的计划，包括增加IPv6支持和在测试中使用虚拟机。</p></li><li><p><strong>OSD重新部署</strong>： 讨论了在需要更改对象存储时自动重新部署OSD的需求。</p></li></ol><p>会议决定：</p><ul><li>为SMB支持创建一个专门的文档，并计划在未来的开发周期中继续推进此功能。</li><li>在Reef发布后开始进行FBM二进制文件的重构工作。</li><li>在Squid发布周期中完成NVMF支持的开发和测试。</li><li>在Squid发布中实现升级历史记录功能。</li><li>在未来的开发中增加更多的测试覆盖，特别是IPv6和虚拟机测试。</li><li>在未来开发中实现OSD的自动重新部署功能。</li></ul><p>此外，会议还讨论了如何更好地收集用户反馈，并提高Ceph的易用性，包括可能的演示和培训，以及与Samba社区的合作。</p><p>会议的目标是为未来的开发工作设定明确的目标和行动计划，并确保Cephadm的进一步发展。</p>",6)])])}const m=t(s,[["render",l]]);export{C as __pageData,m as default};
